#!/usr/bin/env python3
# Regenerates tests/pipeline-layout-check-modules.h: small HAND-WRITTEN SPIR-V modules (not translator output, not Apple output) for tests/pipeline-layout-check-unit.c.
# Each module declares descriptor variables of the kinds the translator emits (sampled image, sampler, storage buffer, input attachment) at chosen (set, binding).
# Usage: python3 tests/fixtures/gen-layout-modules.py   (needs spirv-as from spirv-tools; the generated header is committed)
# SPDX-License-Identifier: MIT
import subprocess, struct, os, sys, tempfile

HEAD = """OpCapability Shader
OpCapability InputAttachment
OpMemoryModel Logical GLSL450
OpEntryPoint %s %%main "main"
%s
"""
TYPES = """%void = OpTypeVoid
%fn = OpTypeFunction %void
%float = OpTypeFloat 32
%uint = OpTypeInt 32 0
%uint_2 = OpConstant %uint 2
%sampler = OpTypeSampler
%image = OpTypeImage %float 2D 0 0 0 1 Unknown
%subpass = OpTypeImage %float SubpassData 0 0 0 2 Unknown
%rta = OpTypeRuntimeArray %uint
%blk = OpTypeStruct %rta
%imgarr = OpTypeArray %image %uint_2
%p_sampler = OpTypePointer UniformConstant %sampler
%p_image = OpTypePointer UniformConstant %image
%p_subpass = OpTypePointer UniformConstant %subpass
%p_imgarr = OpTypePointer UniformConstant %imgarr
%p_blk = OpTypePointer StorageBuffer %blk
"""
PTR = {"sampler": "p_sampler", "image": "p_image", "subpass": "p_subpass", "imgarr": "p_imgarr", "ssbo": "p_blk"}

def module(stage, vars_):
    # vars_: list of (name, kind, set, binding)
    exe = "OriginUpperLeft" if stage == "Fragment" else None
    s = HEAD % (stage, ("OpExecutionMode %main OriginUpperLeft" if exe else ""))
    for i, (n, k, st, b) in enumerate(vars_):
        s += "OpName %%%s \"%s\"\n" % (n, n)
    s += "OpDecorate %rta ArrayStride 4\nOpDecorate %blk Block\nOpMemberDecorate %blk 0 Offset 0\n"
    for (n, k, st, b) in vars_:
        s += "OpDecorate %%%s DescriptorSet %d\nOpDecorate %%%s Binding %d\n" % (n, st, n, b)
        if k == "subpass":
            s += "OpDecorate %%%s InputAttachmentIndex %d\n" % (n, b % 4)
    s += TYPES
    for (n, k, st, b) in vars_:
        sc = "StorageBuffer" if k == "ssbo" else "UniformConstant"
        s += "%%%s = OpVariable %%%s %s\n" % (n, PTR[k], sc)
    s += "%main = OpFunction %void None %fn\n%entry = OpLabel\nOpReturn\nOpFunctionEnd\n"
    return s

MODS = {
    # all four kinds, distinct bindings; layout derived from it must match exactly
    "clean_fs": ("Fragment", [("tex", "image", 0, 0), ("smp", "sampler", 0, 1), ("buf", "ssbo", 0, 2), ("fbf", "subpass", 0, 3)]),
    # the shape of pipefail_18d04777d220e041: a constexpr-style sampler and an input attachment on ONE binding (40)
    "collide_fs": ("Fragment", [("tex", "image", 0, 16), ("smp", "sampler", 0, 39), ("cxs", "sampler", 0, 40), ("fbf0", "subpass", 0, 40), ("fbf1", "subpass", 0, 41)]),
    # one storage buffer at binding 2 (type / stage / set mismatch cases are made by the test through the LAYOUT it checks against)
    "buf_fs": ("Fragment", [("buf", "ssbo", 0, 2)]),
    "buf_vs": ("Vertex", [("buf", "ssbo", 0, 3)]),
    "smp_fs": ("Fragment", [("smp", "sampler", 0, 3)]),
    "set1_fs": ("Fragment", [("buf", "ssbo", 1, 0)]),
    "arr_fs": ("Fragment", [("texs", "imgarr", 0, 4)]),
}

def main():
    out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "pipeline-layout-check-modules.h")
    with tempfile.TemporaryDirectory() as d:
        txt = ["/* GENERATED by tests/fixtures/gen-layout-modules.py (spirv-as); hand-written descriptor-variable modules, NOT translator / Apple output. SPDX-License-Identifier: MIT */\n"]
        for name, (stage, vars_) in MODS.items():
            src = os.path.join(d, name + ".spvasm"); dst = os.path.join(d, name + ".spv")
            open(src, "w").write(module(stage, vars_))
            subprocess.check_call(["spirv-as", "--target-env", "vulkan1.2", src, "-o", dst])
            subprocess.check_call(["spirv-val", "--target-env", "vulkan1.2", dst])
            w = struct.unpack("<%dI" % (os.path.getsize(dst) // 4), open(dst, "rb").read())
            txt.append("static const uint32_t k_lm_%s[] = {\n" % name)
            for i in range(0, len(w), 8):
                txt.append("    " + ",".join("0x%08x" % x for x in w[i:i + 8]) + ",\n")
            txt.append("};\n")
        open(out, "w").write("".join(txt))
    print("wrote", out)

if __name__ == "__main__":
    sys.exit(main())
